/**
 * D2Client.dll `0x6fb4cce0` (`0x6fb4cad0` -> `0x6fb8f0dc..0x6fb8f37c`):
 * Resolves the short Town NPC greeting `soundId` (`Sounds.txt` rows `3480..4569`, `Stream = 1`)
 * played when opening an NPC interaction menu without an immediate auto-pop scrolling speech box.
 *
 * - `mode === 2`: return greeting (`greetingReturnId` at `+0x0C`, used when `S2C 0x91` return flag is set)
 * - `mode === 0` (default): 50% coin flip between `greetingId` (`+0x00`) and `greetingInactiveId` (`+0x04`),
 *   followed by a 1-in-3 roll for `greetingTimeId + timeOfDay` (`+0x08`, `0..2`).
 * - `mode === 1`: starts from `greetingId` (`+0x00`) with 1-in-3 roll for `greetingTimeId + timeOfDay`.
 */
export function resolveNpcGreetingSoundId113c(
  hcIdx: number,
  options?: {
    readonly mode?: 0 | 1 | 2 | undefined
    readonly timeOfDay?: 0 | 1 | 2 | undefined
    readonly rng?: (() => number) | undefined
  },
): number {
  const row = NPC_GREETING_ROWS_BY_HCIDX_113C[hcIdx]
  if (!row) return 0
  const mode = options?.mode ?? 0
  if (mode === 2) {
    return row.greetingReturnId || row.greetingId || row.greetingInactiveId || 0
  }
  const rng = options?.rng ?? Math.random
  let ecx = row.greetingId
  if (mode === 0 && row.greetingInactiveId > 0) {
    if (ecx === 0 || (Math.floor(rng() * 2) & 1) === 0) {
      ecx = row.greetingInactiveId
    }
  }
  if (row.greetingTimeId > 0) {
    if (ecx === 0 || Math.floor(rng() * 3) === 0) {
      const tod = options?.timeOfDay ?? (Math.min(2, Math.max(0, Math.floor(rng() * 3))) as 0 | 1 | 2)
      const timeCandidate = row.greetingTimeId + tod
      if (!isUnshippedSoundId113c(timeCandidate)) {
        ecx = timeCandidate
      }
    }
  }
  if (ecx === 0 && row.greetingInactiveId > 0) {
    ecx = row.greetingInactiveId
  }
  return ecx
}

/**
 * D2Client.dll `0x6faf9130` -> `0x6faf8590`:
 * Resolves the 16-bit `.tbl` `wStringId` for `Talk -> Introduction` from `0x6fba37a8`,
 * taking into account per-character-class intro overrides (`classMatch` at `+0x0B`).
 */
export function resolveNpcIntroStringId113c(
  hcIdx: number,
  act?: number,
  playerClass?: number,
): number | undefined {
  const row =
    (act !== undefined ? NPC_TALK_TABLE_113C.find((r) => r.hcIdx === hcIdx && r.act === act) : undefined) ??
    NPC_TALK_TABLE_113C.find((r) => r.hcIdx === hcIdx)
  if (!row || row.entries.length === 0) return undefined
  if (playerClass !== undefined && playerClass >= 0) {
    // 0x6faf914e..0x6faf91a2: Act 5 second class-specific intro slots
    if (hcIdx === 513 && playerClass === 4 && row.entries[15]) return row.entries[15].stringId
    if (hcIdx === 514 && playerClass === 2 && row.entries[11]) return row.entries[11].stringId
    if (hcIdx === 515 && playerClass === 3 && row.entries[10]) return row.entries[10].stringId
    // 0x6faf91ab: entries[1].classMatch === playerClass
    if (row.entries[1] && row.entries[1].classMatch === playerClass) {
      return row.entries[1].stringId
    }
  }
  return row.entries[0]?.stringId
}

/**
 * Resolves the canonical `.tbl` key (`AkaraIntroSorGossip1`, `AkaraIntroGossip1`,
 * `WarrivAct1IntroGossip1`, etc.) for an NPC's `Introduction` speech according to
 * `D2Client.dll 0x6faf9130 -> 0x6fba37a8`, matching the exact voice selected by
 * `resolveNpcIntroStringId113c`.
 */
export function resolveNpcIntroTblKey113c(
  hcIdx: number,
  act?: number,
  playerClass?: number,
  fallbackNpcTxtKey?: string,
): string | undefined {
  const introStrId = resolveNpcIntroStringId113c(hcIdx, act, playerClass)
  if (introStrId === 0) {
    return 'WarrivAct1IntroGossip1'
  }
  if (introStrId !== undefined && introStrId > 0) {
    const byId = CANONICAL_NPC_MSG_ID_TO_TBL_KEY[introStrId]
    if (byId) return byId
  }
  const desc = getTownNpcDescriptorByHcIdx(hcIdx)
  const lookupKey = (fallbackNpcTxtKey ?? desc?.npcTxtKey ?? '').toLowerCase()
  return (
    (desc?.greetingKey && desc.greetingKey !== desc.npcTxtKey ? desc.greetingKey : undefined) ??
    NPC_CANONICAL_INTRO_KEYS[lookupKey]
  )
}

/**
 * D2Client.dll `0x6faf91e0` -> `0x6faf8590` / `0x6faf6910`:
 * Resolves a 16-bit `.tbl` `wStringId` for `Talk -> Gossip` from `0x6fba37a8`.
 */
export function resolveNpcGossipStringId113c(
  hcIdx: number,
  options?: {
    readonly act?: number | undefined
    readonly playerClass?: number | undefined
    readonly gossipIndex?: number | undefined
  },
): number | undefined {
  const row =
    (options?.act !== undefined
      ? NPC_TALK_TABLE_113C.find((r) => r.hcIdx === hcIdx && r.act === options.act)
      : undefined) ?? NPC_TALK_TABLE_113C.find((r) => r.hcIdx === hcIdx)
  if (!row || row.entries.length <= 2) return undefined
  const candidates = row.entries.slice(2).filter((e, idx, arr) => {
    if (e.stringId === row.entries[0]?.stringId) return false
    // Exclude trailing second class-intro entries for Malah (j=15), Nihlathak (j=11), Qual-Kehk (j=10)
    if ((hcIdx === 513 || hcIdx === 514 || hcIdx === 515) && idx === arr.length - 1) {
      const key = CANONICAL_NPC_MSG_ID_TO_TBL_KEY[e.stringId]
      if (key && key.includes('Intro')) return false
    }
    if (options?.playerClass !== undefined && options.playerClass >= 0) {
      return e.classMatch === 7 || e.classMatch === options.playerClass
    }
    return true
  })
  const pool = candidates.length > 0 ? candidates : row.entries.slice(2)
  const idx = Math.max(0, options?.gossipIndex ?? 0) % pool.length
  return pool[idx]?.stringId
}

/**
 * Resolves the canonical `.tbl` key (`AkaraGossip1`, `AkaraGossip2`, etc.) for an NPC's
 * `Talk -> Gossip` speech according to `D2Client.dll 0x6faf91e0 -> 0x6faf6910`, matching
 * the exact class/act-filtered voice selected by `resolveNpcGossipStringId113c`.
 */
export function resolveNpcGossipTblKey113c(
  hcIdx: number,
  options?: {
    readonly act?: number | undefined
    readonly playerClass?: number | undefined
    readonly gossipIndex?: number | undefined
    readonly fallbackNpcTxtKey?: string | undefined
  },
): string | undefined {
  const gossipStrId = resolveNpcGossipStringId113c(hcIdx, {
    act: options?.act,
    playerClass: options?.playerClass,
    gossipIndex: options?.gossipIndex,
  })
  if (gossipStrId !== undefined && gossipStrId > 0) {
    const byId = CANONICAL_NPC_MSG_ID_TO_TBL_KEY[gossipStrId]
    if (byId) return byId
  }
  const desc = getTownNpcDescriptorByHcIdx(hcIdx)
  const lookupKey = (options?.fallbackNpcTxtKey ?? desc?.npcTxtKey ?? '').toLowerCase()
  const list = NPC_CANONICAL_GOSSIP_KEYS[lookupKey]
  if (list && list.length > 0) {
    const idx = Math.max(0, options?.gossipIndex ?? 0) % list.length
    return list[idx]
  }
  return undefined
}

/**
 * D2Client.dll `0x6fb2d3c0` (`NPC_OpenScrollingSpeech`) & `0x6fb2d200` (`Object_OpenScrollingSpeech`):
 * Resolves the `Sounds.txt` speech `soundId` (`3488..4655`, `Stream = 1`) from `0x6fb8f398`
 * for any NPC or standalone scrolling speech box.
 */
export function resolveNpcSpeechSoundId113c(options: {
  readonly stringId?: number | undefined
  readonly tblKey?: string | undefined
  readonly hcIdx?: number | undefined
  readonly npcTxtKey?: string | undefined
  readonly topic?: 'intro' | 'gossip' | 'quest' | undefined
  readonly act?: number | undefined
  readonly playerClass?: number | undefined
  readonly gossipIndex?: number | undefined
}): number {
  const topic = options.topic ?? 'intro'
  const hcIdx =
    options.hcIdx ??
    (options.npcTxtKey ? getTownNpcDescriptorByName(options.npcTxtKey)?.hcIdx : undefined)

  // 1. Explicit stringId lookup against 0x6fb8f398 (864 entries)
  if (options.stringId !== undefined && options.stringId >= 0) {
    // Warriv Act 1 (hcIdx 155) intro: resolveNpcIntroMsgIdByTblKey('WarrivAct1IntroGossip1')
    // returns 1 (Paladin intro) for C2S 0x31 because 0 is empty in D2MessageStrc[8], whereas
    // 0x6fb8f398 maps stringId 0 -> 4336 (warriv_act1_intro) and 1 -> 4337 (warriv_act1_intro_pal).
    if (
      options.stringId === 1 &&
      topic === 'intro' &&
      hcIdx === 155 &&
      options.playerClass !== 3
    ) {
      return 4336
    }
    const byStrId = NPC_SCROLL_SPEECH_SOUND_BY_STRING_ID_113C[options.stringId]
    if (byStrId !== undefined && byStrId > 0) {
      return byStrId
    }
  }

  // 2. Explicit .tbl key lookup
  if (options.tblKey) {
    const byKey = NPC_SCROLL_SPEECH_SOUND_BY_TBL_KEY_113C[options.tblKey]
    if (byKey !== undefined && byKey > 0) {
      return byKey
    }
  }

  // 3. Topic-based fallback via 0x6fba37a8 (NPC_TALK_TABLE_113C) and canonical NPC keys
  const desc =
    (hcIdx !== undefined ? getTownNpcDescriptorByHcIdx(hcIdx) : undefined) ??
    (options.npcTxtKey ? getTownNpcDescriptorByName(options.npcTxtKey) : undefined)
  const lookupKey = (options.npcTxtKey ?? desc?.npcTxtKey ?? '').toLowerCase()

  if (topic === 'intro') {
    if (hcIdx !== undefined) {
      const introStrId = resolveNpcIntroStringId113c(hcIdx, options.act, options.playerClass)
      if (introStrId !== undefined) {
        const sId = NPC_SCROLL_SPEECH_SOUND_BY_STRING_ID_113C[introStrId]
        if (sId !== undefined && sId > 0) return sId
      }
    }
    const introKey =
      (desc?.greetingKey && desc.greetingKey !== desc.npcTxtKey ? desc.greetingKey : undefined) ??
      NPC_CANONICAL_INTRO_KEYS[lookupKey]
    if (introKey) {
      const sId = NPC_SCROLL_SPEECH_SOUND_BY_TBL_KEY_113C[introKey]
      if (sId !== undefined && sId > 0) return sId
    }
  }

  if (topic === 'gossip') {
    if (hcIdx !== undefined) {
      const gossipStrId = resolveNpcGossipStringId113c(hcIdx, {
        act: options.act,
        playerClass: options.playerClass,
        gossipIndex: options.gossipIndex,
      })
      if (gossipStrId !== undefined) {
        const sId = NPC_SCROLL_SPEECH_SOUND_BY_STRING_ID_113C[gossipStrId]
        if (sId !== undefined && sId > 0) return sId
      }
    }
    const gossipList = NPC_CANONICAL_GOSSIP_KEYS[lookupKey]
    if (gossipList && gossipList.length > 0) {
      const idx = Math.max(0, options.gossipIndex ?? 0) % gossipList.length
      const gKey = gossipList[idx]!
      const sId = NPC_SCROLL_SPEECH_SOUND_BY_TBL_KEY_113C[gKey]
      if (sId !== undefined && sId > 0) return sId
    }
  }

  if (topic === 'quest' && desc?.questLines) {
    const firstQuestKey = Object.values(desc.questLines)[0]
    if (firstQuestKey) {
      const sId = NPC_SCROLL_SPEECH_SOUND_BY_TBL_KEY_113C[firstQuestKey]
      if (sId !== undefined && sId > 0) return sId
    }
  }

  return 0
}
